    OR NOT EXISTS(SELECT 1 FROM comparator_strict.execution_jobs WHERE job_key='ce1-ce200-f7646f5558181bf56fec4c8346a4' AND status='running' AND operation_hash='f7646f5558181bf56fec4c8346a47aaa952d3f06972b769a742e1bec36c58196' AND deadline_at>clock_timestamp()) THEN RAISE EXCEPTION 'ce200_lease'; END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) INTO data FROM (SELECT id,md5(to_jsonb(p)::text) AS source_row_md5 FROM public.carrefour_products p WHERE (published IS TRUE AND (display_name ~* '(agua|aigua|water|yogu|yogh|iogur|patat|papat)' OR category_name ~* '(agua|aigua|water|yogu|yogh|iogur|patat|papat)|b[ií]fidus'))
      AND id COLLATE "C" > 'VC4AECOMM-682991' COLLATE "C" ORDER BY id COLLATE "C" LIMIT 500) q;
  payload:=jsonb_build_object('job_key','ce1-ce200-f7646f5558181bf56fec4c8346a4','operation_hash','f7646f5558181bf56fec4c8346a47aaa952d3f06972b769a742e1bec36c58196',
    'project_ref','gkffvigcnsesbaihycay','captured_at',started,'kind','fingerprints','store','carrefour',
    'cursor','VC4AECOMM-682991','rows',data,'row_count',jsonb_array_length(data),'elapsed_ms',extract(epoch FROM clock_timestamp()-started)*1000);
